with open('/tmp/data.csv', 'r') as f:
    rows = list(csv.DictReader(f))
group_values = {}
for row in rows:
    if row['group'] == 'south':
        value = float(row['value'])
        if value not in group_values:
            group_values[value] = []
        group_values[value].append(row['value'])
median_value = sorted(group_values.values())[len(group_values.values()) // 2]
print(f"FINAL: {median_value:.2f}")

